from typing import List, Optional

from taf.rfrl.csv4all.resources.test_cases.csv4all_test import test_logger
from taf.rfrl.csv4all.resources.test_cases.module_test import ModuleTest
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator
from taf.rfrl.csv4all.resources.utilities.test_global_constants import KPI_PER_TEST_CASE


class RadioModuleResetTest(ModuleTest):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool, calculate_kpi: Optional[bool] = True, kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 stop_test_after_fail: bool = False, l3_call_method: Optional[callable] = None,
                 detailed_console_log: bool = True, collect_passed_logs: int = 0):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report,
                         calculate_kpi, kpi_targets, use_dcap, qc_domain, qc_id, qc_project, customers_list,
                         report_comment, sw_build, topology, stop_test_after_fail, l3_call_method,
                         detailed_console_log, collect_passed_logs=collect_passed_logs)
        self.module_type = "radio"
        self.kpi_to_calculate = KPI_PER_TEST_CASE.get("Radio Reset")

    def test_operation(self, node):
        rmod = next(node.modules_for_test)
        self.set_proper_kpi_to_calculate(node, rmod)
        test_logger(f"Starting reset: {rmod}")
        self.add_allowed_specific_faults(node, ["10", "4589"], rmod)
        self.add_faults_on_shared_rmod(node, rmod, self.allowed_faults_on_shared_rmods)
        node.reset_unit(rmod, reset_type="HARD", timeout=900)
        if self.l3_call_method:
            self.set_l3_all_dependent_cells(node, rmod)

    @method_decorator()
    def set_proper_kpi_to_calculate(self, node, rmod_dn: str):
        mapped_cells = node.radioModules[rmod_dn].get("Mapped Cells")
        for rmod, rmod_details in node.radioModules.items():
            if rmod != rmod_dn:
                _rmod_mapped_cells = rmod_details.get("Mapped Cells")
                same_cells = [cell for cell in mapped_cells if cell in _rmod_mapped_cells]
                if same_cells and "kpi51c" not in self.kpi.kpi_names:
                    self.kpi.kpi_names.append("kpi51c")
                    return
        if "kpi51c" in self.kpi.kpi_names:
            self.kpi.kpi_names.remove("kpi51c")
